import Foundation

enum Language: String, CaseIterable {
    case ru, en, fr, es
    var name: String {
        switch self { case .ru: return "Русский"; case .en: return "English"; case .fr: return "Français"; case .es: return "Español" }
    }
    static func preferred(saved: String?, system: String?) -> Language {
        if let saved, let language = Language(rawValue: saved) { return language }
        return allCases.first { system?.hasPrefix($0.rawValue) == true } ?? .en
    }
    func text(_ key: String) -> String {
        guard let pair = Self.strings[key] else { return key }
        switch self { case .ru: return pair.0; case .en: return pair.1; case .fr: return Self.french[key] ?? pair.1; case .es: return Self.spanish[key] ?? pair.1 }
    }
